package dev.pocketengine.features.local.project;
import static org.junit.Assert.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;import org.junit.*;
public final class ProjectPackageSelectionTest {
 private Path root;private static final byte[] RAW={0,(byte)255,3};
 @Before public void create()throws Exception{root=Files.createTempDirectory("pw-package-subset-");Files.createDirectories(root.resolve("src/empty"));Files.createDirectory(root.resolve("other"));Files.write(root.resolve("src/main.txt"),"source".getBytes(StandardCharsets.UTF_8));Files.write(root.resolve("src/.env"),"KNOWN_PRIVATE_NEVER_PACKAGE".getBytes(StandardCharsets.UTF_8));Files.write(root.resolve("binary.bin"),RAW);Files.write(root.resolve("unselected.txt"),"unselected".getBytes(StandardCharsets.UTF_8));Files.write(root.resolve("other/unselected.txt"),new byte[]{9});}
 @After public void close()throws Exception{try(var all=Files.walk(root)){for(Path path:all.sorted(Comparator.reverseOrder()).toArray(Path[]::new))Files.deleteIfExists(path);}}
 private JSONObject origin()throws Exception{return new JSONObject().put("projectId","11111111-1111-1111-1111-111111111111").put("checkoutId","22222222-2222-2222-2222-222222222222").put("sourceDigest","a".repeat(64)).put("name","Original source package");}
 private ProjectPackageArchive.Frozen capture(JSONArray selected)throws Exception{return ProjectPackageArchive.capture(root.toFile(),origin(),"source_project","",false,selected);}
 private Set<String> filePaths(JSONObject manifest)throws Exception{Set<String> result=new TreeSet<>();JSONArray files=manifest.getJSONArray("files");for(int i=0;i<files.length();i++)result.add(files.getJSONObject(i).getString("path"));return result;}
 @Test public void actualSubsetUsesOriginalCodecAndPreservesSelectedBinaryEmptyDirsAndExplicitOmissions()throws Exception{var frozen=capture(new JSONArray().put("src").put("binary.bin"));JSONObject manifest=frozen.manifest();assertEquals(Set.of("src/main.txt","binary.bin"),filePaths(manifest));Set<String> directories=new TreeSet<>();for(int i=0;i<manifest.getJSONArray("directories").length();i++)directories.add(manifest.getJSONArray("directories").getString(i));assertEquals(Set.of("src","src/empty"),directories);assertTrue(manifest.getJSONArray("omitted").toString().contains("not_selected"));assertTrue(manifest.getJSONArray("omitted").toString().contains("credential_or_private_configuration"));var out=new java.io.ByteArrayOutputStream();ProjectPackageArchive.write(frozen,out);Path archive=Files.createTempFile("pw-subset-roundtrip-",".zip");try{Files.write(archive,out.toByteArray());var decoded=ProjectPackageArchive.read(archive.toFile());assertEquals(frozen.identity,decoded.identity);assertArrayEquals(RAW,decoded.file("binary.bin"));assertFalse(new String(out.toByteArray(),StandardCharsets.ISO_8859_1).contains("KNOWN_PRIVATE_NEVER_PACKAGE"));assertEquals(Set.of("src/main.txt","binary.bin"),decoded.files().keySet());}finally{Files.delete(archive);}}
 @Test public void omittedSelectionKeepsByteIdenticalLegacyWholePackageIdentityAndZip()throws Exception{var old=ProjectPackageArchive.capture(root.toFile(),origin(),"source_project","",false);var same=ProjectPackageArchive.capture(root.toFile(),origin(),"source_project","",false,null);assertEquals(old.identity,same.identity);var left=new java.io.ByteArrayOutputStream();var right=new java.io.ByteArrayOutputStream();ProjectPackageArchive.write(old,left);ProjectPackageArchive.write(same,right);assertArrayEquals(left.toByteArray(),right.toByteArray());assertTrue(old.files().containsKey("unselected.txt"));}
 @Test public void unsafeMissingPrivateLinkedAndGeneratedSelectionsCannotBecomeAnExpandedArchiveScope()throws Exception{Files.createDirectories(root.resolve("node_modules"));Files.createDirectories(root.resolve("build"));Files.write(root.resolve("build/output.js"),new byte[]{1});Files.createSymbolicLink(root.resolve("linked"),root.resolve("src"));for(String path:new String[]{"../escape","/tmp",".","missing","linked","linked/main.txt","src/.env","node_modules","build/output.js"})assertThrows(Exception.class,()->capture(new JSONArray().put(path)));var generated=ProjectPackageArchive.capture(root.toFile(),origin(),"source_project","",true,new JSONArray().put("build/output.js"));assertEquals(Set.of("build/output.js"),generated.files().keySet());assertThrows(IllegalArgumentException.class,()->ProjectPackageArchive.capture(root.toFile(),origin(),"web_output","src/main.txt",true,new JSONArray().put("src")));}
 @Test public void subsetFilterRunsBeforeArchiveBodyReadAndDoesNotTurnLiteralPathsIntoGlobs()throws Exception{Files.write(root.resolve("other/too-large.bin"),new byte[ProjectPackageArchive.MAX_FILE_BYTES+1]);assertEquals(Set.of("binary.bin"),capture(new JSONArray().put("binary.bin")).files().keySet());assertThrows(Exception.class,()->ProjectPackageArchive.capture(root.toFile(),origin(),"source_project","",false));Files.createDirectory(root.resolve("src2"));Files.write(root.resolve("src2/not-selected.txt"),new byte[]{1});var selected=capture(new JSONArray().put("src"));assertEquals(Set.of("src/main.txt"),selected.files().keySet());assertThrows(Exception.class,()->capture(new JSONArray().put("src/*")));}
 @Test public void reviewedManifestCannotContainExtraPayloadsOrSilentlyLoseAnExplicitSelectedPath()throws Exception{var frozen=capture(new JSONArray().put("binary.bin"));JSONObject manifest=frozen.manifest();ProjectPackageArchive.requireSelectionManifest(manifest,new JSONArray().put("binary.bin"));assertThrows(SecurityException.class,()->ProjectPackageArchive.requireSelectionManifest(manifest,new JSONArray().put("src")));JSONObject extra=new JSONObject(manifest.toString());extra.getJSONArray("files").put(new JSONObject().put("path","unselected.txt"));assertThrows(SecurityException.class,()->ProjectPackageArchive.requireSelectionManifest(extra,new JSONArray().put("binary.bin")));JSONObject omitted=new JSONObject(manifest.toString());omitted.getJSONArray("omitted").put(new JSONObject().put("path","binary.bin").put("reason","not_selected"));assertThrows(SecurityException.class,()->ProjectPackageArchive.requireSelectionManifest(omitted,new JSONArray().put("binary.bin")));}
 @Test public void selectionIsBoundedCanonicalExplicitAndNeverSilentlyFallsBackToWholeProject()throws Exception{JSONArray selected=ProjectPackageArchive.normalizedSelection(new JSONArray().put("src/main.txt").put("binary.bin"));assertEquals("binary.bin",selected.getString(0));for(JSONArray invalid:new JSONArray[]{new JSONArray(),new JSONArray().put("src").put("src"),new JSONArray().put(1),new JSONArray().put(JSONObject.NULL),new JSONArray().put(String.join("/",Collections.nCopies(41,"a")))})assertThrows(Exception.class,()->ProjectPackageArchive.normalizedSelection(invalid));JSONArray huge=new JSONArray();for(int i=0;i<=ProjectPackageArchive.MAX_FILES;i++)huge.put("p"+i);assertThrows(IllegalArgumentException.class,()->ProjectPackageArchive.normalizedSelection(huge));assertThrows(Exception.class,()->capture(new JSONArray().put("src/empty")));}
 @Test public void explicitEntryMustBeInTheSelectedSourceSubsetAndAncestorDirectoriesAreOnlyStructural()throws Exception{assertThrows(IllegalArgumentException.class,()->ProjectPackageArchive.capture(root.toFile(),origin(),"source_project","unselected.txt",false,new JSONArray().put("binary.bin")));var frozen=capture(new JSONArray().put("src/main.txt"));assertEquals(Set.of("src/main.txt"),frozen.files().keySet());assertEquals(1,frozen.manifest().getJSONArray("directories").length());assertEquals("src",frozen.manifest().getJSONArray("directories").getString(0));}
}
